def is_valid_email(s):
    """Check if s is a valid email address."""
    if not isinstance(s, str) or not s:
        return False

    if ' ' in s or s.count('@') != 1:
        return False

    local, domain = s.split('@')

    if not local or not domain:
        return False

    if '.' not in domain:
        return False

    parts = domain.split('.')
    if not parts[-1] or len(parts[-1]) < 2:
        return False

    return True

